/bin/bash -lc "python3 - <<'PY'
import ast,json,subprocess,hashlib,copy
from pathlib import Path
r=json.loads(subprocess.check_output(['python3','tools.py','resolve','run://r-001'],text=True))
p=json.loads(Path('proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
 t=schema.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(int,float),'integer':int}
 if t: assert isinstance(value,types[t]),(path,t,type(value))
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),(path,'missing')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=props.keys(),(path,'extra')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
ancestor=ast.parse(Path('history_g2_r0021_target_live.py').read_text())
def dump(n): return ast.dump(n,include_attributes=False)
def methods(tree,cls='Model'):
 return {n.name:n for n in next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==cls).body if isinstance(n,ast.FunctionDef)}
old=methods(ancestor)
canonical=None
for v in p['variants']:
 path=Path(v['file'])
 assert path.name==v['file'] and path.suffix=='.py'
 source=path.read_text()
